"""Campaign layout: real Würzburg photographs, portrait concepts and a human art encounter."""
import html,json,re,hashlib
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
def e(value):return html.escape(str(value),quote=True)
def lines(values):return ''.join(f'<span>{e(v)}</span>' for v in values)
def replace_values(v,config):
 if isinstance(v,str):return v.replace('{price}',str(config['photoPortraitPriceEUR'])).replace('{min}',str(config['minimumLiveGroup']))
 if isinstance(v,list):return [replace_values(x,config) for x in v]
 if isinstance(v,dict):return {k:replace_values(x,config) for k,x in v.items()}
 return v

def redesign(doc,c,lang,config,all_content):
 n=replace_values(json.loads((ROOT/'campaign.json').read_text())[lang],config)
 rel='./' if lang=='en' else '../'
 def asset(name):return rel+'assets/'+name
 langs=['en','zh-cn','zh-tw','ja','de']
 language_links=''.join(f'<a href="{rel+(l+"/" if l!="en" else "")}" lang="{all_content[l]["lang"]}" hreflang="{all_content[l]["lang"]}" '+('aria-current="page"' if l==lang else '')+f'>{e(all_content[l]["label"])}</a>' for l in langs)
 nav=''.join(f'<a href="#{id}">{e(t)}</a>' for id,t in zip(['experiences','artist','films','faq'],c['nav']))
 header=f'''<header class="site-header"><a class="brand" href="{rel}" aria-label="Phil Splash — The Million Painter"><span class="brand-name">PHIL SPLASH<span class="brand-star" aria-hidden="true">✳</span></span><span class="brand-sub">THE MILLION PAINTER / WÜRZBURG</span></a><nav class="desktop-nav" aria-label="Navigation">{nav}</nav><div class="header-actions"><details class="languages"><summary><span aria-hidden="true">◎</span>{e(c['label'])}<span aria-hidden="true">⌄</span></summary><div>{language_links}</div></details><a class="button button-small" href="#enquire">{e(c['navBook'])} ↗</a></div></header>'''
 hero=f'''<section class="campaign-hero" aria-labelledby="hero-title"><picture class="hero-backdrop"><source media="(max-width:700px)" srcset="{asset('city-dusk-small.webp')}"><img src="{asset('city-dusk.webp')}" width="2400" height="1587" fetchpriority="high" alt="Festung Marienberg, Würzburg · Photo: Dietmar Rabich / CC BY-SA 4.0"></picture><div class="hero-shade" aria-hidden="true"></div><div class="hero-coordinate">49°47′ N &nbsp; 9°56′ E<span>WÜRZBURG, BAVARIA</span></div><div class="hero-copy"><p class="eyebrow"><span class="live-dot" aria-hidden="true"></span>{e(n['heroEyebrow'])}</p><h1 id="hero-title">{lines(n['heroTitle'])}</h1><p class="hero-intro">{e(n['heroLead'])}</p><div class="hero-buttons"><a class="button" href="#photo">{e(n['photoCTA'])}<span aria-hidden="true">↗</span></a><a class="button button-outline" href="#enquire" data-offer="live">{e(n['liveCTA'])}<span aria-hidden="true">↗</span></a></div></div><a class="hero-ticket" href="#photo" aria-label="{e(n['ticket']+' — '+n['conceptLabel'])}"><div class="ticket-top"><span>{e(n['ticket'])}</span><span>01 / 03</span></div><img src="{asset('portrait-city-color.webp')}" alt="{e(n['designs'][0][1]+' — '+n['conceptLabel'])}" width="1024" height="1536"><div class="ticket-bottom"><strong>WÜRZBURG ORIGINALS</strong><span>{e(n['ticketNote'])}</span><small>{e(n['conceptLabel'])}</small></div></a><a class="hero-scroll" href="#city"><span>{e(n['explore'])}</span><span aria-hidden="true">↓</span></a><span class="hero-photo-credit"><a href="#image-credits">PHOTO / DIETMAR RABICH · CC BY-SA 4.0</a></span></section>'''
 strip=f'''<div class="trust-strip"><span>WÜRZBURG <i aria-hidden="true">×</i> PHIL SPLASH</span><span>1 MILLION PORTRAITS <i aria-hidden="true">✳</i> YOURS NEXT?</span><span>{e(c['heroNote'])}</span></div>'''
 image_names=['city-bridge.webp','city-palace.webp','city-market.webp']
 citycards=''.join(f'''<article class="city-card city-card-{i}"><img src="{asset(image_names[i])}" width="1600" height="1067" alt="{e(title)} · Würzburg" loading="lazy"><span class="city-card-number">0{i+1}</span><div class="city-card-caption"><h3>{e(title)}</h3><p>{e(text)}</p></div></article>''' for i,(title,text) in enumerate(n['places']))
 city=f'''<section class="city-section section-wrap" id="city" aria-labelledby="city-title"><div class="split-heading" data-reveal><div><p class="eyebrow">{e(n['cityLabel'])}</p><h2 id="city-title">{lines(n['cityTitle'])}</h2></div><p>{e(n['cityIntro'])}</p></div><div class="city-grid">{citycards}</div><div class="section-foot"><span>01 / WÜRZBURG</span><a class="text-link" href="https://www.wuerzburg.de/en/" target="_blank" rel="noopener">{e(c['visitLink'])} ↗</a></div></section>'''
 keys=['color','ink','original']; files=['portrait-city-color.webp','portrait-city-ink.webp','portrait-1.webp']
 design_payload=[{'key':keys[i],'file':asset(files[i]),'label':title,'heading':heading,'description':description,'isConcept':i<2} for i,(title,heading,description) in enumerate(n['designs'])]
 tabs=''.join(f'<button type="button" class="design-tab" data-design="{keys[i]}" aria-pressed="{"true" if i==0 else "false"}" aria-controls="portrait-stage"><span>0{i+1}</span>{e(t[0])}</button>' for i,t in enumerate(n['designs']))
 steps=''.join(f'<div><span>{e(i)}</span><p>{e(t)}</p></div>' for i,t in n['steps'])
 collection=f'''<section class="collection-section" id="experiences" aria-labelledby="collection-title"><div class="collection-layout section-wrap" id="photo"><div class="collection-art" data-reveal><div class="artwork-label"><span>WÜRZBURG ORIGINALS</span><span>PHIL SPLASH ↗</span></div><div class="artwork-plinth"><figure id="portrait-stage"><img id="design-image" src="{asset(files[0])}" alt="{e(n['designs'][0][1]+' — '+n['conceptLabel'])}" width="1024" height="1536" loading="lazy"></figure><span class="artwork-seal" aria-hidden="true">YOU<br>WERE<br>HERE. ↗</span></div><p id="design-credit">{e(n['conceptLabel'])}</p><div class="artwork-label artwork-label-bottom"><span>49°47′ N / 9°56′ E</span><span id="design-edition">01 / CITY COLOR</span></div></div><div class="collection-copy" data-reveal><p class="eyebrow">{e(n['collectionLabel'])}</p><h2 id="collection-title">{lines(n['collectionTitle'])}</h2><p>{e(n['collectionText'])}</p><div class="design-selector" role="group" aria-label="{e(n['selectDesign'])}">{tabs}</div><div class="design-description" aria-live="polite"><h3 id="design-heading">{e(n['designs'][0][1])}</h3><p id="design-description">{e(n['designs'][0][2])}</p></div><div class="collection-price"><span>€{config['photoPortraitPriceEUR']}</span><p>{e(c['perPortrait'])}</p></div><a class="button" href="#enquire" data-offer="photo">{e(n['chooseCTA'])}<span aria-hidden="true">↗</span></a><p class="fine-print">{e(n['collectionFoot'])}</p></div><div class="portrait-steps">{steps}</div></div></section>'''
 live=f'''<section class="live-section section-wrap" id="live" aria-labelledby="live-title"><div class="live-copy" data-reveal><p class="eyebrow">{e(n['liveLabel'])}</p><h2 id="live-title">{lines(n['liveTitle'])}</h2><p>{e(n['liveText'])}</p><div class="live-fact">{e(n['liveFact'])}</div><ul class="checklist">{''.join('<li>'+e(t)+'</li>' for t in c['liveBullets'][1:])}</ul><a class="button button-dark" href="#enquire" data-offer="live">{e(c['liveCTA'])} ↗</a><p class="fine-print">{e(c['liveFoot'])}</p></div><figure class="live-photo" data-reveal><img src="{asset('street.webp')}" alt="{e(c['liveCaption'])}" width="1280" height="720" loading="lazy"><figcaption>{e(n['liveImageLabel'])}</figcaption><a class="live-photo-play" href="#films"><span aria-hidden="true">▶</span>{e(n['liveFilm'])}</a><div class="live-photo-sticker" aria-hidden="true">MEET<br>THE<br>ARTIST. ↗</div></figure></section>'''
 etching=f'''<section class="engraving-section" id="artist" aria-labelledby="artist-title"><div class="engraving-heading section-wrap" data-reveal><p class="eyebrow">{e(n['etchLabel'])}</p><h2 id="artist-title">{lines(n['etchTitle'])}</h2><p>{e(n['etchText'])}</p></div><figure class="engraving-figure"><img src="{asset('phil-mainbridge-engraving.webp')}" width="1536" height="1024" alt="{e(n['etchCaption'])}" loading="lazy"><span class="engraving-stamp">{e(n['etchTag'])}</span><figcaption>{e(n['etchCaption'])}</figcaption></figure><div class="artist-bio section-wrap"><div class="artist-nameplate"><span>PHIL SPLASH</span><strong>THE MILLION<br>PAINTER.</strong><a class="text-link" href="{config['artistWebsite']}" target="_blank" rel="noopener">{e(c['artistLink'])} ↗</a></div><div><p>{e(c['artistText'])}</p><p>{e(c['artistText2'])}</p></div></div></section>'''
 portraits=''.join(f'<figure><img src="{asset("portrait-"+str(i+1)+".webp")}" alt="{e(c["artAlt"][i])}" width="1131" height="1600" loading="lazy"><figcaption>PHIL SPLASH / ORIGINAL 0{i+1}</figcaption></figure>' for i in range(3))
 originals=f'''<section class="originals-section section-wrap" aria-labelledby="originals-title"><div class="split-heading" data-reveal><div><p class="eyebrow">{e(n['originalLabel'])}</p><h2 id="originals-title">{e(n['originalTitle'])}</h2></div><p>{e(n['originalText'])}</p></div><div class="portrait-gallery">{portraits}</div></section>'''
 old_films=doc[doc.index('<section class="films-section"'):doc.index('<section class="visit ')]
 old_films=old_films.replace(e(c['filmTitle']),e(n['filmTitle']))
 tail=doc[doc.index('<section class="faq '):]
 tail=tail.replace('<h2 id="contact-title">'+e(c['contactTitle']).replace('\n','<br>')+'</h2>','<h2 id="contact-title">'+lines(n['contactTitle'])+'</h2>')
 design_options=''.join(f'<option value="{keys[i]}">{e(x[0]+" / "+x[1])}</option>' for i,x in enumerate(n['designs']))
 field=f'<div id="design-field" hidden><label for="portrait-design">{e(n["designField"])}</label><select id="portrait-design" name="design">{design_options}</select></div>'
 tail=tail.replace('<div class="form-grid">',field+'<div class="form-grid">',1)
 credits=json.loads((ROOT/'assets/photo-credits.json').read_text())
 credit_links=''.join(f'<li><a href="{e(d["source"])}" target="_blank" rel="noopener">{e(name)} — {e(d["author"])}</a> · <a href="{e(d["licenseUrl"])}" target="_blank" rel="noopener">{e(d["license"])}</a></li>' for name,d in credits.items())
 credits_html=f'<details class="legal-details" id="image-credits"><summary>{e(n["photoCredit"])}</summary><p>{e(n["creditIntro"])}</p><ul>{credit_links}</ul></details>'
 tail=tail.replace('<p class="credit">'+e(c['credit'])+'</p>',credits_html)
 oldbrand='<span class="brand-name">phil splash<span class="brand-star">✳</span></span>'
 tail=tail.replace(oldbrand,'<span class="brand-name">PHIL SPLASH<span class="brand-star">✳</span></span>')
 dock=f'<nav class="mobile-booking" aria-label="{e(c["navBook"])}"><a href="#enquire" data-offer="live">{e(n["stickyLive"])} ↗</a><a href="#photo">{e(n["stickyPhoto"])} ↗</a></nav>'
 design_config=json.dumps({'designs':design_payload,'conceptLabel':n['conceptLabel'],'originalLabel':n['originalLabel']},ensure_ascii=False).replace('<','\\u003c')
 head=doc[:doc.index('<body')]
 head=head.replace('wuerzburg-illustration.webp','city-dusk.webp').replace(e(c['caption']),'Festung Marienberg, Würzburg · Photo: Dietmar Rabich / CC BY-SA 4.0').replace('content="#f7f4ec"','content="#131614"')
 head=head.replace('as="image" fetchpriority="high">','as="image" media="(min-width:701px)" fetchpriority="high">')
 for filename in ['style.css','app.js','favicon.svg']:
  digest=hashlib.sha256((ROOT/filename).read_bytes()).hexdigest()[:10]
  head=head.replace(rel+filename+'"',rel+filename+'?v='+digest+'"')
 head=head.replace('</head>',f'<link rel="preload" href="{asset("city-dusk-small.webp")}" as="image" media="(max-width:700px)" fetchpriority="high"><script id="design-config" type="application/json">{design_config}</script></head>')
 tail=tail.replace('</footer>','</footer>'+dock)
 return head+f'<body class="campaign" id="top"><a class="skip" href="#main">{e(c["skip"])}</a>'+header+'<main id="main">'+hero+strip+city+collection+live+etching+originals+old_films+tail
